import bodyParser from 'body-parser';
import dotenv from 'dotenv';
import endpointRouter from './src/endpoint/endpoint.router';

dotenv.config();

const app = express();
app.use(bodyParser.json());
app.use(bodyParser.urlencoded({ extended: true }));

// routes
app.use('/', (req, res) => res.status(200).send({message: 'Welcome'}));
app.use('/endpoint', endpointRouter);

app.listen(process.env.PORT, process.env.IPCONFIG, () => console.log(`Process listening on ${process.env.PORT}`));

export default app;
